/* 아이콘 하나를 그립니다. ic("tower") · ic("tower", 18) */
const ICLEGACY = {"\u{1F3EE}":"lantern","\u{1F56F}":"candle","\u{1F5E1}":"sword","\u{1F4FF}":"beads",
  "\u{1F311}":"moonDark","\u{1F409}":"dragon","\u{1F98A}":"fox","\u{1FAB7}":"lotus","\u2694":"swords","\u{1F702}":"alcFire"};
function ic(name, size, style){
  const p = ICONS[name] || ICONS[ICLEGACY[name]];
  if(!p) return "";
  const s = size || 16;
  return `<svg class="ic" viewBox="0 0 24 24" width="${s}" height="${s}" fill="none" stroke="currentColor"`
       + ` stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"`
       + `${style?` style="${style}"`:""}>${p}</svg>`;
}

