/* 과목별 성장 — 기본 능력치는 과정 한계 안에서, 고유 효과는 수료 레벨에 따라 계산합니다. */
const SUBJECT_TRAINING={
 s1: {near:{atk:1.2,def:.4},far:{atk:.8,agi:.8},per:{atkP:.02},bonus:{atkP:.05}},
 s2: {near:{atk:1,res:.6},far:{atk:.6,res:1},per:{critD:.03},bonus:{crit:.01}},
 s3: {near:{atk:.8,men:.8},far:{atk:.8,agi:.8},per:{boss:.025,quality:.003},bonus:{quality:.03}},
 s4: {near:{atk:1,agi:.6},far:{atk:.8,men:.8},per:{crit:.004},bonus:{critD:.10}},
 s5: {near:{def:1.2,men:.4},far:{def:.8,men:.8},per:{defP:.02},bonus:{hpP:.06}},
 s6: {near:{def:1,res:.6},far:{def:.6,res:1},per:{hpP:.02,heal:.005},bonus:{heal:.05}},
 s7: {near:{def:1.2,agi:.4},far:{def:.8,agi:.8},per:{defP:.012,hpP:.008},bonus:{defP:.05}},
 s8: {near:{def:1,men:.6},far:{def:.6,men:1},per:{rest:.025,heal:.005},bonus:{hpP:.05}},
 s9: {near:{agi:1,atk:.6},far:{agi:1.2,atk:.4},per:{spd:.012},bonus:{crit:.01}},
 s10:{near:{agi:1,men:.6},far:{agi:1,res:.6},per:{loot:.015},bonus:{quality:.02}},
 s11:{near:{agi:1,res:.6},far:{agi:.8,res:.8},per:{crit:.003,spd:.006},bonus:{critD:.06}},
 s12:{near:{agi:1,def:.6},far:{agi:1.2,men:.4},per:{exp:.02,loot:.005},bonus:{exp:.05}},
 s13:{near:{men:1,def:.6},far:{men:1.2,res:.4},per:{rest:.03,know:.005},bonus:{heal:.05}},
 s14:{near:{men:1,res:.6},far:{men:.8,res:.8},per:{quality:.01,know:.01},bonus:{quality:.03}},
 s15:{near:{men:1,def:.6},far:{men:1.2,agi:.4},per:{snGuard:.01},bonus:{snGuard:.03}},
 s16:{near:{men:.8,res:.8},far:{men:.6,res:1},per:{heal:.015,know:.005},bonus:{heal:.06}},
 s17:{near:{res:1,agi:.6},far:{res:1.2,agi:.4},per:{crit:.002,mana:.015},bonus:{crit:.01}},
 s18:{near:{res:1,men:.6},far:{res:1.2,men:.4},per:{study:.02,mana:.01},bonus:{study:.05}},
 s19:{near:{res:1,atk:.6},far:{res:1.2,atk:.4},per:{spd:.008,atkP:.01},bonus:{atkP:.05}},
 s20:{near:{res:1,def:.6},far:{res:.8,men:.8},per:{snGuard:.005,heal:.01},bonus:{rest:.08}},
};
const SUBJECT_MILESTONES=[{lv:5,mul:1},{lv:10,mul:2},{lv:20,mul:3}];
const CLASS_EFFECTS={atkP:"공격력",defP:"방어력",hpP:"생명력",crit:"치명타 확률",critD:"치명타 피해",
  boss:"업귀 피해",spd:"공격 속도",loot:"전리품 획득 확률",quality:"법구 품질 상승 확률",
  rest:"체력·이성 자연 회복",heal:"치유·보호막 위력",exp:"경험치 획득",know:"지식 획득",
  mana:"파장 재생",study:"수업 보상",snGuard:"이성 소모 감소"};
function combatStyle(){
  if(["근거리","원거리"].includes(S.combatStyle)) return S.combatStyle;
  return /활|궁|총|원거리|사격|투척/.test(S.weapon||"")?"원거리":"근거리";
}
function subjectLevel(id){ return Math.max(0,Math.floor(Number(S.sub[id]?.lv)||0)); }
function subjectGrowth(id,style=combatStyle()){
  return SUBJECT_TRAINING[id]?.[style==="원거리"?"far":"near"]||{};
}
function subjectEffects(id,lv=subjectLevel(id)){
  const t=SUBJECT_TRAINING[id]; if(!t) return {};
  const v={};
  for(const [k,n] of Object.entries(t.per)) v[k]=n*lv;
  for(const m of SUBJECT_MILESTONES) if(lv>=m.lv)
    for(const [k,n] of Object.entries(t.bonus)) v[k]=(v[k]||0)+n*m.mul;
  return v;
}
function subjectMod(key){ return SUBJECTS.reduce((n,s)=>n+(subjectEffects(s.id)[key]||0),0); }
function subjectStat(key){ return SUBJECTS.reduce((n,s)=>n+(subjectGrowth(s.id)[key]||0)*subjectLevel(s.id),0); }
function statGrowthText(values){
  return Object.entries(values).map(([k,v])=>`${STATS.find(s=>s.k===k).n} +${Number(v.toFixed(1))}`).join(" · ");
}
function classEffectText(values,mul=1){
  return Object.entries(values).filter(([,v])=>v>0).map(([k,v])=>`${CLASS_EFFECTS[k]||k} +${Number((v*mul*100).toFixed(1))}${["crit","critD","quality","loot"].includes(k)?"%p":"%"}`).join(" · ")||"아직 수료한 레벨이 없습니다.";
}
function lootQualityChance(){ return clamp(mod("quality"),0,.60); }
function setCombatStyle(style){
  if(!["근거리","원거리"].includes(style)) return;
  S.combatStyle=style;
  renderMain(); renderNav(); renderTop(); save();
  if(typeof syncUp==="function") syncUp(true);
}
function combatStyleHTML(){
  return `<div class="row"><b>전투 거리</b><span class="seg">${["근거리","원거리"].map(t=>`<button class="${combatStyle()===t?"on":""}" aria-pressed="${combatStyle()===t}" onclick="setCombatStyle('${t}')">${t}</button>`).join("")}</span></div>
    <div class="tiny muted" style="margin-top:7px">장인·마무기 모두 선택 가능 · 언제든 변경할 수 있습니다.<br>근거리는 공격·방호, 원거리는 민첩·공명 위주로 과목별 성장치가 달라집니다. 바꾸면 수료한 과목의 성장치도 함께 바뀝니다.</div>`;
}

