function newState(){
  const sub={}; SUBJECTS.forEach(s=>sub[s.id]={lv:0,p:0,fav:false});
  const res={}; RESEARCH.forEach(r=>res[r.id]=0);
  return {
    made:false, v:1,
    name:"이름 없는 차사", gender:"기타", line:"장인", weapon:"", combatStyle:null,
    hall:"dorm", title:"첫 번째 밤", intro:"", bio:"", color:"var(--gold)", av:"lantern", avImg:null, avSrc:"",
    base:{atk:3,def:3,agi:3,men:2,res:2},
    bonus:{atk:0,def:0,agi:0,men:0,res:0},
    course:1, exp:0, lvl:1,
    hp:100, sn:100,
    mana:1200, know:240, rin:1800, sari:3, lotus:0,
    ledger:[],        // 용돈 기입장 — 륜이 드나든 기록 {t:시각, a:금액, k:항목}
    t:0,              // 명계 분
    lastReal:Date.now(),
    speed:1,
    weather:0, wNext:360,
    sub, res,
    lesson:null,      // {plan:[id..], idx, left}
    plans:[ {n:"시간표 1", list:["s17","s17","s5","s5"]}, {n:"기초 수행", list:["s13","s13","s17","s5"]}, null,null,null,null ],
    study:null,       // {id, left, total}
    book:null,        // {id, left}
    inv:{},           // 상점 품목 보유
    buffs:[],         // {key,v,left,n}
    ward:false,
    quests:{cleared:0, gate:0, log:[], room:null},
    pass:3, passNext:720, outing:{done:{}, souv:[]},
    fest:{marks:0, todayMarks:0, basket:0, visits:0, stamps:[], souv:null, total:265000},
    rel:[], friends:[],
    msgs:[], chatReset:3, chatFrom:0, chatTab:"전체", chatMode:"RP", chatFilter:"모두",
    homeReset:1,
    news:[], notes:[],
    place:"plaza", examHist:{},
    dayStamp:0, playFrom:Date.now(),
  };
}
function save(){ try{ S.lastReal=Date.now(); localStorage.setItem(SAVEKEY, JSON.stringify(S)); }catch(e){} }
function load(){
  try{ const r=localStorage.getItem(SAVEKEY); if(!r) return null;
       const o=JSON.parse(r); const base=newState();
       /* 채팅 기록 비우기 — 표식을 올리면 그 다음 접속 때 한 번 더 비웁니다.
          chatFrom 보다 먼저 올라온 글은 서버에 남아 있어도 가져오지 않습니다. */
       if(o.hall && /^h[1-4]$/.test(o.hall)) o.hall="dorm";   // 옛 숙사 → 기숙사
       if((o.chatReset||0) < 3){ o.msgs=[]; o.chatReset=3; o.chatFrom=Date.now(); }
       /* 거처 성장 비우기 — 표식을 올리면 그 다음 접속 때 한 번 더 0단계로 돌아갑니다.
          거주지와 월세 계약도 함께 풀어 처음부터 고르게 합니다. */
       if((o.homeReset||0) < 1){
         o.home={stage:0, due:0, auto:(o.home&&o.home.auto!==undefined)?o.home.auto:true};
         o.homeReset=1;
       }
       if(o.av && ICLEGACY[o.av]) o.av=ICLEGACY[o.av];
       if(o.av && !ICONS[o.av]) o.av="lantern";
       if(o.chatFilter===undefined) o.chatFilter=o.chatTab==="1:1"&&["RP","오너"].includes(o.dmTab)?o.dmTab:"모두";
       /* 제거된 옛 콘텐츠의 저장 기록 정리. 나머지 캐릭터 진행도는 유지합니다. */
       if(o.title==="첫 번째 별") o.title="첫 번째 밤";
       if(o.place==="lounge") o.place="plaza";
       delete o.lounge;
       delete o.pets;
       delete o.mile;
       delete o.snack;
       if(o.ct){ delete o.ct.pet; delete o.ct.dispatch; }
       if(o.mart) delete o.mart.m5;
       if(Array.isArray(o.ach)) o.ach=o.ach.filter(id=>!["a32","a33","a34"].includes(id));
       if(o.book&&o.book.id==="b13") o.book=null;
       if(o.place==="pets"||o.place==="petshop") o.place="plaza";
       return Object.assign(base,o, {sub:Object.assign(base.sub,o.sub||{}), res:Object.assign(base.res,o.res||{})});
  }catch(e){ return null; }
}
function resetAll(){ if(confirm("모든 기록을 지우고 처음부터 시작할까요?")){ localStorage.removeItem(SAVEKEY); location.reload(); } }

/* ── 유틸 ───────────────────────── */
const $=(s,r=document)=>r.querySelector(s);
const $$=(s,r=document)=>[...r.querySelectorAll(s)];
const rnd=(a,b)=>Math.floor(Math.random()*(b-a+1))+a;
const pick=a=>a[Math.floor(Math.random()*a.length)];
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const nf=n=>{ n=Math.floor(n);
  if(n>=100000000) return Number((n/100000000).toFixed(2))+"억";
  if(n>=10000) return Number((n/10000).toFixed(n>=100000?0:2))+"만";
  return n.toLocaleString("ko-KR"); };
const esc=s=>String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
function d5(n){ let t=0; for(let i=0;i<n;i++) t+=rnd(1,5); return t; }

function toast(msg,kind=""){
  if(typeof QUIET!=="undefined" && QUIET) return;   // 밀린 진행을 돌리는 중에는 조용히
  const d=document.createElement("div"); d.className="toast "+kind; d.innerHTML=msg;
  $("#toasts").appendChild(d);
  while($("#toasts").children.length>3)$("#toasts").firstElementChild.remove();
  setTimeout(()=>{ d.style.transition=".3s"; d.style.opacity=0; d.style.transform="translateX(16px)"; setTimeout(()=>d.remove(),320); },3400);
}

/* ── 서버 조회 공통 조건 ─────────────
   다른 탭으로 넘어가거나 화면을 끈 동안에는 서버에 물어볼 이유가 없습니다.
   각 화면의 반복 조회는 이 함수를 먼저 확인하고, 돌아오면 그때 다시 받아옵니다.
   창이 숨어 있는 사이 쌓인 변화는 돌아온 직후 한 번에 따라잡습니다. */
function pollAwake(){
  return typeof document==="undefined" || document.visibilityState!=="hidden";
}

/* ── 새 버전 감지 ───────────────────
   운영진이 게임 파일을 새로 올리면, 열어 둔 창은 예전 코드를 그대로 쓰고 있습니다.
   파일의 서버 표식(ETag / 수정 시각)을 5분마다 확인해, 바뀌었으면 띠를 띄웁니다.
   운영진이 따로 버전을 적어 넣을 필요는 없습니다. */
/* User-facing release notices. Keep newest first; update with every shipped request. */
