function updateNoticeStorageKey(){
 let actor='local';try{actor=(typeof ACCT!=='undefined'&&ACCT?.id)||S?.sb?.id||'local';}catch(_){}
 return 'mmjy:update-notice-seen:'+actor;
}
function updateNoticeUnreadCount(){
 try{const seen=localStorage.getItem(updateNoticeStorageKey()),index=UPDATE_NOTICES.findIndex(n=>n.id===seen);return index<0?UPDATE_NOTICES.length:index;}catch(_){return 0;}
}
function updateNoticeUnread(){return updateNoticeUnreadCount()>0;}
function unreadCountHTML(count,extra=''){
 return count>0?`<span class="count-badge ${extra}" aria-label="읽지 않음 ${count}개">${count>99?'99+':count}</span>`:'';
}
function openUpdateNotices(){
 if(UPDATE_NOTICES.length)try{localStorage.setItem(updateNoticeStorageKey(),UPDATE_NOTICES[0].id);}catch(_){}
 modal('업데이트 안내',`<div class="tiny muted" style="margin-bottom:12px">최근 변경 사항부터 표시합니다.</div><div class="update-notice-list">${UPDATE_NOTICES.map(n=>`<article class="update-notice"><div class="spread"><b>${esc(n.title)}</b><time class="tiny muted" datetime="${esc(n.date)}">${esc(n.date)}</time></div><ul>${n.items.map(item=>`<li>${esc(item)}</li>`).join('')}</ul></article>`).join('')||'<p>등록된 안내가 없습니다.</p>'}</div>`);
 renderTop();
}
const UPDFILES=["index.html", "game.css", "game.js", "config.js", "notifications.js", "gameplay.js", "social.js", "community.js", "visuals.js", "coop.js", "notification-worker.js", "manifest.webmanifest"];
let UPDSTAMP=null, UPDSHOWN=false;
function updStamps(){
  if(location.protocol==="file:") return Promise.resolve(null);   // 로컬 파일은 확인 불가
  return Promise.all(UPDFILES.map(f=>
    fetch(f+"?_v="+Date.now(), {method:"HEAD", cache:"no-store"})
      .then(r=>r.ok ? (r.headers.get("etag")||r.headers.get("last-modified")||r.headers.get("content-length")||"") : "")
      .catch(()=>"")
  )).then(a=>a.join("|"));
}
function updBarShow(){
  if(UPDSHOWN) return; UPDSHOWN=true;
  const el=document.getElementById("updbar"); if(!el) return;
  el.innerHTML = `새 버전이 올라왔습니다. 새로고침하면 바뀐 내용이 적용됩니다.`
    + `<button onclick="updReload()">새로고침</button>`
    + `<button class="x" onclick="updDismiss()" title="나중에">✕</button>`;
  el.className="on";
}
function updReload(){ try{ save(); }catch(e){} location.reload(true); }
function updDismiss(){ const el=document.getElementById("updbar"); if(el){ el.className=""; el.innerHTML=""; } }
function updCheck(){
  updStamps().then(now=>{
    if(now===null) return;
    if(UPDSTAMP===null){ UPDSTAMP=now; return; }
    if(now && now!==UPDSTAMP) updBarShow();
  });
}
function updStart(){ updCheck(); setInterval(updCheck, 5*60*1000);
  document.addEventListener("visibilitychange",()=>{ if(!document.hidden) updCheck(); }); }

/* ── 테마 ───────────────────────────
   어두운 테마가 기본입니다. 고른 값은 브라우저에 따로 저장되므로
   입학 전 화면에서도 유지됩니다. */
const THEMEKEY="mmjy_theme";
let THEME=(function(){ try{ return localStorage.getItem(THEMEKEY)==="light"?"light":"dark"; }catch(e){ return "dark"; } })();
function applyTheme(){
  document.documentElement.setAttribute("data-theme", THEME);
  const mt=document.querySelector('meta[name="theme-color"]');
  if(mt) mt.setAttribute("content", THEME==="light"?"#f7f2fd":"#0a0616");
}
function setTheme(t){
  THEME = t==="light" ? "light" : "dark";
  try{ localStorage.setItem(THEMEKEY, THEME); }catch(e){}
  applyTheme();
  if(typeof renderTop==="function") renderTop();
  if(S && S.made && typeof renderMain==="function") renderMain();
}
function toggleTheme(){ setTheme(THEME==="light"?"dark":"light"); }
applyTheme();

/* 접속자 — 공유 기록이 연결됐을 때만, 실제 러너만 셉니다. part6 에서 덮어씁니다. */
function onlineChip(){ return ""; }

/* 재사용 대기 — 시계가 현실과 같이 흐르므로, 예전에 "시간을 쓴다"로 막던 행동은
   이제 쿨다운으로 막습니다. 값은 명계 분(=현실 분) 단위의 절대 시각입니다. */
function coolLeft(k){ if(!S.cool) S.cool={}; return Math.max(0, (S.cool[k]||0) - S.t); }
function coolSet(k, mins){ if(!S.cool) S.cool={}; S.cool[k] = S.t + mins; }
/* 지금 사무전에 있는 사람 — 공유 기록이 연결됐을 때만 실제 러너가 나옵니다. part6 에서 덮어씁니다. */
function hereHTML(){
  return `<div class="card pad" style="margin-top:14px">
    <div class="sect-t">사무전에 함께 있는 학생</div>
    <div class="tiny muted">공유 기록이 연결되면 지금 접속해 있는 러너가 여기에 보입니다.</div>
  </div>`;
}

/* ── 시간 ───────────────────────── */
/* 명계력 1024년 무명달 1일 오전 0:00  =  2026년 11월 2일 0시 (한국 시간)
   현실 1분이 흐르면 명계도 1분 흐릅니다. 시계는 접속 여부와 상관없이
   현실 시각에서 바로 계산하므로, 모든 러너가 같은 날짜·같은 시각을 봅니다. */
const GAME_EPOCH = Date.UTC(2026,10,1,15,0,0);   // KST 기준이라 기기 시간대와 무관
function nowMin(){ return (Date.now()-GAME_EPOCH)/60000; }
function cal(){
  const total=Math.floor(S&&S.made?S.t:nowMin());
  const day=Math.floor(total/1440);
  const min=total%1440;
  const y=1024+Math.floor(day/360);
  const m=Math.floor((day%360)/30);
  const dd=(day%30)+1;
  const h=Math.floor(min/60), mm=min%60;
  const ap=h<12?"오전":"오후"; const h12=h%12===0?12:h%12;
  return {y,m:MONTHS[m],dd,h,mm,str:`${ap} ${h12}:${String(mm).padStart(2,"0")}`,
          date:`명계력 ${y}년 ${MONTHS[m]} ${dd}일`, day, min};
}
function hhmm(mins){ mins=Math.max(0,Math.ceil(mins));
  const h=Math.floor(mins/60), m=mins%60;
  return h>0 ? `${h}시간 ${m}분` : `${m}분`; }

/* ── 능력치 / 보정 ───────────────── */
function stat(k){
  /* 예전 저장본의 수업 능력치는 최소 보장값입니다. 새 성장치를 중복해서 더하지 않습니다. */
  const base=Number(S.base[k])||0, old=Number(S.bonus[k])||0;
  return +(base+Math.max(old,Math.min(Math.max(0,statCap(k)-base),subjectStat(k)))).toFixed(1);
}
function statCap(k){ return STATCAP[k][clamp(S.course-1,0,6)]; }
function hallBonus(k){ return 0; }   /* 거주지 혜택은 part3의 HALLBONUS 표가 담당합니다 */
/* 거주지 찾기 — 모르는 값이 들어와도 기숙사로 떨어뜨려 화면이 죽지 않게 합니다 */
function homeOf(id){ return HALLS.find(h=>h.id===id) || HALLS[0]; }
/* 페어 이름 — 공유 기록이 연결됐을 때만 값이 있습니다 (part6 에서 덮어씁니다) */
function pairName(){ return ""; }
function effStat(k){
  let v=stat(k)+hallBonus(k);
  const hpR=S.hp/100, snR=S.sn/100;
  if(k==="atk"||k==="def"){ if(hpR<=.2) v*=.5; else if(hpR<=.5) v*=.8; }
  if(k==="agi"){ if(snR<=.2) v*=.5; else if(snR<=.5) v*=.8; }
  if(k==="atk") v*=1+mod("atkP");
  if(k==="def") v*=1+mod("defP");
  return Math.max(1,Math.round(v));
}
/* 누적 보정치: 연구 + 버프 + 서고 + 날씨 + 거주지 */
function mod(key){
  let v=subjectMod(key);
  const R=S.res;
  if(key==="mana")  v+=R.r1*.06;
  if(key==="study") v+=R.r3*.02;
  if(key==="atkP")  v+=R.r4*.04;
  if(key==="defP")  v+=R.r5*.02;
  if(key==="hpP")   v+=R.r5*.04;
  if(key==="gold")  v+=R.r6*.04;
  if(key==="know")  v+=R.r7*.04;
  if(key==="exp")   v+=R.r8*.04;
  if(key==="loot")  v+=R.r9*.025;
  if(key==="crit")  v+=R.r12*.03;
  if(key==="atkP")  v+=R.r13*.02;
  if(key==="hpP")   v+=R.r13*.02;
  S.buffs.forEach(b=>{ if(b.key===key) v+=b.v; });
  if(S.book){ const b=BOOKS.find(x=>x.id===S.book.id); if(b&&b.k===key) v+=b.v; }
  const w=WEATHERS[S.weather]; if(w.k===key) v+=w.v;
  return v;
}
function manaRate(){ return (18 + S.course*8 + S.lvl*0.6)*(1+mod("mana")); }
function maxMana(){ return Math.round(manaRate()*60*(8 + S.res.r2*4)); }
function power(){
  let p=0;
  p+=effStat("atk")*120+effStat("def")*100+effStat("agi")*90+effStat("men")*80+effStat("res")*110;
  let sl=0; SUBJECTS.forEach(s=>sl+=S.sub[s.id].lv); p+=sl*34;
  let rl=0; RESEARCH.forEach(r=>rl+=S.res[r.id]); p+=rl*58;
  p+=S.course*900 + S.lvl*40;
  return Math.round(p*(1+mod("atkP")*.5));
}
function expNeed(){ return Math.round(260*Math.pow(1.11,S.lvl-1)); }
function gainExp(n,exact=false){
  n=exact?Math.round(n):Math.round(n*(1+mod("exp")));
  S.exp+=n;
  let up=0;
  while(S.exp>=expNeed()){ S.exp-=expNeed(); S.lvl++; up++; }
  if(up) toast(`수행 단계 상승 · <b>Lv ${S.lvl}</b>`,"good");
  return n;
}
function gainRin(n,exact=false){ n=exact?Math.round(n):Math.round(n*(1+mod("gold"))); S.rin+=n; return n; }
function gainKnow(n,exact=false){ n=exact?Math.round(n):Math.round(n*(1+mod("know"))); S.know+=n; return n; }

function damageHP(n){ S.hp=Math.max(1,S.hp-n);
  if(S.hp<=1){ toast("체력이 바닥났습니다. 전투 불능 상태로 퇴장합니다.","bad"); } }
function damageSN(n){
  n=Math.max(0,Math.round(n*(1-clamp(mod("snGuard"),0,.60))));
  const before=S.sn; S.sn=Math.max(1,S.sn-n);
  if(S.sn<=1){ toast("이성이 바닥났습니다. 정상적인 판단이 어렵습니다.","bad"); }
  return before-S.sn;
}

/* ── 메인 틱 ─────────────────────── */
let TICK=null;
function startTick(){ if(TICK) clearInterval(TICK);
  LASTSTEP=Date.now();
  TICK=setInterval(()=>{ const n=Date.now(); const mins=(n-LASTSTEP)/60000;
    if(mins<=0){ LASTSTEP=n; return; }
    LASTSTEP=n; S.lastReal=n; step(mins); },1000); }
let LASTSTEP=Date.now();
function step(mins){
  if(!S.made) return;
  S.t=nowMin();

  // 파장 회복
  S.mana=Math.min(maxMana(), S.mana+manaRate()*mins);

  // 체력/이성 회복
  const rr=1+mod("rest");
  S.hp=Math.min(100,S.hp+0.055*mins*rr);
  S.sn=Math.min(100,S.sn+0.045*mins*rr);

  // 버프 감소
  let bch=false;
  S.buffs.forEach(b=>b.left-=mins);
  if(S.buffs.some(b=>b.left<=0)){ S.buffs=S.buffs.filter(b=>b.left>0); bch=true; }
  if(S.book){ S.book.left-=mins; if(S.book.left<=0){ toast(`「${BOOKS.find(b=>b.id===S.book.id).n}」 열람 효과가 끝났습니다.`); S.book=null; } }

  // 날씨
  S.wNext-=mins;
  if(S.wNext<=0){ S.weather=rnd(0,WEATHERS.length-1); S.wNext=rnd(240,480);
    pushNews(`[석탑] 명계의 기상이 「${WEATHERS[S.weather].n}」로 바뀌었습니다.`); }

  // 통행패
  S.passNext-=mins;
  if(S.passNext<=0){ if(S.pass<3){ S.pass++; toast("통행패 1장이 발급되었습니다."); } S.passNext=720; }

  // 수업
  if(S.lesson){
    S.lesson.left-=mins;
    while(S.lesson && S.lesson.left<=0){
      finishPeriod();
    }
  }
  // 수행(연구)
  if(S.study){
    S.study.left-=mins;
    if(S.study.left<=0) finishResearch();
  }
  // 하루 경계
  const d=cal().day;
  if(d!==S.dayStamp){ S.dayStamp=d; onNewDay(); }

  // 자동 소식/채팅
  if(Math.random()<0.012*mins) pushNews(makeNews());
  // NPC 답변은 Supabase의 전체·RP 발언 트리거에서 공용 기록으로 생성합니다.

  renderTop(); renderNav();
  // 의뢰 제목 선택창은 자동 갱신으로 DOM을 교체하지 않습니다.
  // 덕분에 구간 선택을 열어 둔 상태에서 1초마다 접히지 않습니다.
  if(["plaza","class","research","exam"].includes(VIEW)) renderMain(true);
  if(Math.random()<0.02) save();
}
function onNewDay(){
  S.fest.basket=0; S.fest.visits=0; S.fest.todayMarks=0;
  S.outing.done={};
  pushNews("[경비] 새 날이 열렸습니다. 문 앞 공양 바구니가 교체되었습니다.");
  toast("새 날입니다. 공양 바구니와 나들이 이야기가 갱신되었습니다.");
}
function pushNews(t){ S.news.unshift({t, time:cal().str}); if(S.news.length>40) S.news.pop(); }
function makeNews(){
  let s=pick(NEWSPOOL);
  return s.replace("{w}",rnd(1,7)).replace("{r}",pick(RANKS).r)
          .replace("{c}",rnd(1,6)).replace("{g}",pick(["S","A","B"]));
}

/* 오프라인 진행 */
let QUIET=false;
function offline(){
  const el=Math.min(Date.now()-(S.lastReal||Date.now()), 24*3600*1000);
  const mins=Math.floor(el/60000);
  if(mins>5){
    QUIET=true;                       // 밀린 진행을 돌리는 동안에는 알림을 띄우지 않습니다
    try{
      const chunk=120; let left=mins;
      while(left>0){ const c=Math.min(chunk,left); step(c); left-=c; }
    } finally { QUIET=false; }
    toast(`자리를 비운 동안 <b>${hhmm(mins)}</b>이 흘렀습니다.`,"good");
  }
}

/* ═══════════════════════════════════════════════════
   상단바 · 내비 · 채팅
   ═══════════════════════════════════════════════════ */
let TOP_EFFECT_OPEN='';
function toggleTopEffects(kind){TOP_EFFECT_OPEN=TOP_EFFECT_OPEN===kind?'':kind;renderTop();}
function topEffectGroup(kind,label,rows){
 if(!rows.length)return '';
 return `<div class="top-effect-group ${TOP_EFFECT_OPEN===kind?'is-open':''}"><button class="buffchip" aria-expanded="${TOP_EFFECT_OPEN===kind}" aria-controls="effects-${kind}" onclick="toggleTopEffects('${kind}')">${label} ${rows.length}개 ▾</button>
 <div class="top-effect-list" id="effects-${kind}" role="region" aria-label="${label} 목록"><b>${label} ${rows.length}개</b>${rows.map(b=>`<div class="top-effect-row"><div class="spread"><span>${esc(b.n)}</span><span>${hhmm(b.left)}</span></div><div class="muted">${esc(b.d||'')}</div></div>`).join('')}</div></div>`;
}
function renderTop(){
  const c=cal(), w=WEATHERS[S.weather];
  const food=typeof mealChips==="function"?mealChips():[],potions=[],others=[];
  for(const b of S.buffs.filter(b=>!b.hide&&b.left>0)){
    const item=SHOP.find(p=>p.n===b.n&&p.type==='buff');
    const potion=typeof POTIONS!=='undefined'?POTIONS.find(p=>p.id===b.pid||p.n===b.n):null;
    const row={...b,d:potion?.d||item?.d||b.d||''};
    if(potion||item?.tag==='물약')potions.push(row);
    else if(item?.tag==='식사')food.push(row);
    else others.push(row);
  }
  const buffs=others.map(b=>`<span class="buffchip"><span class="dot" style="background:${b.c||"var(--violet)"}"></span>${esc(b.n)} <span>${hhmm(b.left)}</span></span>`).join('')+topEffectGroup('food','음식 효과',food)+topEffectGroup('potion','물약 효과',potions);
  const bookChip=S.book?`<span class="buffchip"><span class="dot" style="background:var(--gold)"></span>「${BOOKS.find(b=>b.id===S.book.id).n}」 <span style="color:var(--s7)">${pairLiveTimer('book',S.book.left)}</span></span>`:"";
  $("#topbar").innerHTML=`
  <div class="tb1">
    <div class="logo logo-top" title="無明長夜"></div>
    <div class="top-avatar">${avatarHTML(34)}</div>
    <div class="top-identity">
      <div class="me-name">${esc(S.name)}${S.line?` <span class="me-line tiny" style="color:var(--s6)">· ${esc(S.line)}</span>`:""}<span class="me-lv">Lv ${S.lvl}</span></div>
      <div class="me-sub">${homeOf(S.hall).n} · ${S.course}과정 · Lv ${S.lvl}</div>
    </div>
    <div class="res-wrap">
      <div class="res" title="파장 — 수행에 쓰입니다. 한도까지만 모입니다">${ic("droplet",13)}<b style="color:var(--blue)">파장</b> ${nf(S.mana)}<span style="color:var(--s7)">/${nf(maxMana())}</span></div>
      <div class="res" title="륜 — 명계의 화폐">${ic("coin",13)}<b style="color:var(--gold)">륜</b> ${nf(S.rin)}</div>
      <div class="res" title="지식 — 수업으로 모읍니다">${ic("book",13)}<b style="color:var(--jadeD)">지식</b> ${nf(S.know)}</div>
      <div class="res" title="사리 — 정화된 영혼의 결정">${ic("orb",13)}<b style="color:var(--violet)">사리</b> ${nf(S.sari)}</div>
      <div class="res" title="연등 — 축제와 업적">${ic("lantern",13)}<b style="color:var(--red)">연등</b> ${nf(S.lotus)}</div>
    </div>
    ${topBrief()}
    <div class="top-actions">
      <button type="button" class="btn sm ghost act-updates" onclick="openUpdateNotices()" title="업데이트 안내" aria-label="업데이트 안내${updateNoticeUnread()?' · 새 소식 있음':''}">${ic("scroll",15)}${unreadCountHTML(updateNoticeUnreadCount(),'update-unread-count')}</button>
      <button class="btn sm ghost act-me" onclick="openMe()" title="내 정보">${ic("user",15)}</button>
      <button class="btn sm ghost act-theme" onclick="toggleTheme()" title="${THEME==="light"?"어두운 테마로":"밝은 테마로"}">${ic(THEME==="light"?"moonDark":"lens",15)}</button>
      <button class="btn sm ghost act-settings" onclick="openSettings()" title="설정">${ic("gear",15)}</button>
    </div>
  </div>
  <div class="mobile-vitals" aria-label="캐릭터 상태">
    ${[
      {key:"hp",label:"체력",value:Math.floor(S.hp),max:100,pct:S.hp},
      {key:"sn",label:"정신력",value:Math.floor(S.sn),max:100,pct:S.sn},
      {key:"xp",label:"경험치",value:Math.floor(S.exp),max:expNeed(),pct:S.exp/expNeed()*100}
    ].map(v=>`<button type="button" class="mobile-vital ${v.key}${v.key!=="xp"&&v.pct<=20?" critical":""}" onclick="openMobileVitals()" aria-label="${v.label} ${v.value.toLocaleString("ko-KR")} / ${v.max.toLocaleString("ko-KR")} · 상세 보기">
      <div class="mobile-vital-text"><span>${v.label}</span><strong>${v.key==="xp"?`${v.pct.toFixed(1)}%`:`${v.value} / ${v.max}`}</strong></div>
      <div class="bar ${v.key}" role="progressbar" aria-label="${v.label}" aria-valuemin="0" aria-valuemax="${v.max}" aria-valuenow="${v.value}"><i style="width:${Math.max(0,Math.min(100,v.pct))}%"></i></div>
    </button>`).join("")}
  </div>
  <div class="tb2">
    <span>${c.date}</span>
    <span class="top-weather">${w.i} ${w.n} <span style="color:var(--s6)">· ${w.d}</span></span>
    ${onlineChip()}
    <button class="btn sm top-rest" onclick="rest()" ${coolLeft('rest')>0?'disabled':''} title="체력·이성 45 회복 · 재사용 대기시간 3시간">${coolLeft('rest')>0?'보건실 · '+hhmm(coolLeft('rest')):'보건실에서 쉬기 (3시간)'}</button>
    ${bookChip}${buffs}
    <span style="margin-left:auto;color:var(--s6)">${c.str}</span>
  </div>`;
}
/* 접은 상단 — 작은 화면에서 머리글이 본문을 밀어내지 않도록, 한 줄로 줄인 요약입니다.
   체력·정신력·경험치를 작은 막대 셋으로, 륜을 숫자로 보여 주고, 나머지(자원 전부,
   막대 상세, 날짜·날씨·보건실·효과)는 눌러서 폅니다. 넓은 화면에서는 숨겨집니다. */
function topBrief(){
  const open=document.body.classList.contains("top-open");
  const pips=[
    {k:"hp", c:"var(--red)",    p:S.hp},
    {k:"sn", c:"var(--violet)", p:S.sn},
    {k:"xp", c:"var(--gold)",   p:S.exp/expNeed()*100}
  ];
  const low=pips.slice(0,2).some(v=>v.p<=20);
  const bars=pips.map(v=>`<i class="tb-pip ${v.k}${v.k!=="xp"&&v.p<=20?" critical":""}"><b style="height:${Math.max(4,Math.min(100,v.p))}%;background:${v.c}"></b></i>`).join("");
  return `<button type="button" class="tb-mini${low?" low":""}" onclick="toggleTop()"
    aria-expanded="${open}" aria-controls="topbar"
    title="체력 ${Math.floor(S.hp)} · 정신력 ${Math.floor(S.sn)} · 륜 ${nf(S.rin)} — 눌러서 ${open?"접기":"펼치기"}">
    <span class="tb-pips" aria-hidden="true">${bars}</span>
    <span class="tb-rin">${ic("coin",12)}${nf(S.rin)}</span>
    <span class="tb-caret" aria-hidden="true">${ic("chevD",13)}</span>
  </button>`;
}
function toggleTop(){
  document.body.classList.toggle("top-open");
  renderTop();
}
function openMobileVitals(){
  modal("캐릭터 상태",`<div style="line-height:2">체력 <b>${Math.floor(S.hp)} / 100</b><br>정신력(이성) <b>${Math.floor(S.sn)} / 100</b><br>경험치 <b>${Math.floor(S.exp).toLocaleString("ko-KR")} / ${expNeed().toLocaleString("ko-KR")}</b> (${(S.exp/expNeed()*100).toFixed(1)}%)</div>`);
}
function setSpeed(){ /* 시간은 현실과 같은 속도로만 흐릅니다 */ }

const NAVDEF=[
 {id:"plaza", ic:ic("gate"), n:"사무전 광장"},
 {id:"study", ic:ic("book"), n:"수업·수행", sub:[{id:"class",n:"강의실"},{id:"research",n:"수행"},{id:"exam",n:"승급 시험"}]},
 {id:"war",   ic:ic("swords"), n:"의뢰·전투", sub:[{id:"quest",n:"의뢰"},{id:"duel",n:"대련"},{id:"tower",n:"석탑"}]},
 {id:"life",  ic:ic("lantern"), n:"생활",      sub:[{id:"shop",n:"매점"},{id:"outing",n:"구역 나들이"},{id:"fest",n:"염라제",bd:"축제"}]},
 {id:"soc",   ic:ic("candle"), n:"교류",      sub:[{id:"map",n:"지도"},{id:"rel",n:"인연·관계"}]},
 {id:"rec",   ic:ic("scroll"), n:"기록",      sub:[{id:"record",n:"기록·성적"}]},
];
function effectiveStatsHTML(){
  return STATS.map(s=>`<div class="mini-stat" data-eff-stat="${s.k}" title="분배·거주지·법구를 반영한 현재 능력치"><span>${esc(s.n)}</span><b>${effStat(s.k)}</b></div>`).join("");
}
function navItemLabel(item){
  if(item.id!=="pairhub")return esc(item.n);
  const mine=typeof pairEnsure==="function"?pairEnsure().mine:null;
  const shared=typeof SOCIAL!=="undefined"&&mine?SOCIAL.pairs.find(p=>String(p.id)===String(mine.id)):null;
  return esc(shared?.pair_name?.trim()||item.n);
}
function renderNav(){
  // 1초 주기 갱신에도 안내도 내부 스크롤 위치를 보존합니다.
  const navHost=document.getElementById("navcol");
  const priorMenu=navHost?.querySelector(":scope > .card:first-child");
  const menuScrollY=priorMenu?.scrollTop||0;
  const navScrollY=navHost?.scrollTop||0;
  renderMobileNav();
  const hpP=S.hp, snP=S.sn;
  const navHTML=NAVDEF.map(g=>{
    if(!g.sub) return `<div class="nav-g"><div class="nav-h ${VIEW===g.id?"on":""}" onclick="go('${g.id}')"><span class="navic">${g.ic}</span>${g.n}</div></div>`;
    const open=navOpen(g);
    return `<div class="nav-g">
      <div class="nav-h ${g.sub.some(s=>s.id===VIEW)?"on":""}" onclick="toggleNav('${g.id}')">
        <span class="navic">${g.ic}</span>${g.n}<span class="ar">${ic(open?"chevD":"chevR",12)}</span></div>
      <div class="nav-sub ${open?"open":""}">
        ${g.sub.map(s=>`<div class="nav-i ${VIEW===s.id?"on":""}" onclick="go('${s.id}')">${navItemLabel(s)}${s.bd?`<span class="bd">${s.bd}</span>`:""}</div>`).join("")}
      </div></div>`;
  }).join("");

  $("#navcol").innerHTML=`
  <div class="card pad" style="margin-bottom:12px">
    <div class="sect-t">안내도</div>${navHTML}
  </div>
  <div class="card pad">
    <div class="spread" style="margin-bottom:6px">
      <div class="sect-t" style="margin:0">내 정보</div>
      <button class="btn sm ghost" onclick="openMe()">열기</button>
    </div>
    <div class="row" style="gap:9px;margin-bottom:7px">
      ${avatarHTML(40)}
      <div><div style="font-weight:600;font-size:14px">${esc(S.name)}</div>
        <div class="tiny muted">${S.course}과정 · Lv ${S.lvl} · ${S.line}${S.line==="마무기"&&S.weapon?`(${esc(S.weapon)})`:""}</div></div>
    </div>
    <div class="tiny muted">수행 ${nf(S.exp)} / ${nf(expNeed())}</div>
    <div class="bar" style="margin:3px 0 8px"><i style="width:${(S.exp/expNeed()*100).toFixed(1)}%"></i></div>
    <div class="tiny muted">체력 ${Math.floor(hpP)} / 100 ${hpP<=20?"<span style='color:var(--red)'>· 중상</span>":hpP<=50?"<span style='color:var(--gold)'>· 부상</span>":""}</div>
    <div class="bar hp" style="margin:3px 0 6px"><i style="width:${hpP}%"></i></div>
    <div class="tiny muted">이성 ${Math.floor(snP)} / 100 ${snP<=20?"<span style='color:var(--red)'>· 광기</span>":snP<=50?"<span style='color:var(--gold)'>· 동요</span>":""}</div>
    <div class="bar sn" style="margin:3px 0 10px"><i style="width:${snP}%"></i></div>
    <hr class="hr">
    <div class="mini-stat"><span>전투력</span><b style="color:var(--gold)">${nf(power())}</b></div>
    ${effectiveStatsHTML()}
    <hr class="hr">
    <div class="tiny muted">${homeOf(S.hall).n} 혜택 · ${typeof hallBenefitText==="function"?hallBenefitText(S.hall):homeOf(S.hall).b}</div>
  </div>`;
  const refreshedMenu=navHost?.querySelector(":scope > .card:first-child");
  if(refreshedMenu && menuScrollY>0) refreshedMenu.scrollTop=menuScrollY;
  if(navHost) navHost.scrollTop=navScrollY;
}
function navOpen(g){ return NAVOPEN[g.id]!==undefined ? NAVOPEN[g.id] : g.sub.some(s=>s.id===VIEW); }
const MOBILE_GROUP_NAMES={study:"수업",war:"의뢰",gearn:"법구",craft:"공방",plaza:"광장",soc:"교류",shopn:"상점",rec:"기록"};
let MOBILE_CHAT_OPEN=false;
function renderMobileNav(){
  document.body.classList.toggle("mobile-game",!!S?.made);
  const nav=document.getElementById("mobile-nav"), sub=document.getElementById("mobile-subnav");
  if(!nav||!sub) return;
  const group=NAVDEF.find(g=>g.id===VIEW||g.sub?.some(s=>s.id===VIEW));
  nav.innerHTML=["study","war","gearn","craft","plaza","soc","shopn","rec"].map(id=>{
    const g=NAVDEF.find(x=>x.id===id); if(!g) return "";
    return `<button class="${group===g?"on":""}" aria-current="${group===g?"page":"false"}" onclick="mobileGroup('${id}')">${g.ic}<span>${MOBILE_GROUP_NAMES[id]}</span></button>`;
  }).join("");
  sub.innerHTML=(group?.sub||[]).map(s=>`<button class="${s.id===VIEW?"on":""}" aria-current="${s.id===VIEW?"page":"false"}" onclick="go('${s.id}')">${navItemLabel(s)}</button>`).join("");
  const selected=sub.querySelector(".on"); if(selected) sub.scrollLeft=Math.max(0,selected.offsetLeft-sub.clientWidth/2+selected.clientWidth/2);
}
function mobileGroup(id){
  const g=NAVDEF.find(x=>x.id===id); if(!g) return;
  if(MOBILE_CHAT_OPEN) toggleMobileChat();
  go(g.sub?.[0]?.id||g.id);
}
function toggleMobileChat(){
  MOBILE_CHAT_OPEN=!MOBILE_CHAT_OPEN;
  document.body.classList.toggle("mobile-chat-open",MOBILE_CHAT_OPEN);
  const b=document.getElementById("mobile-chat-toggle");
  b.textContent=MOBILE_CHAT_OPEN?"채팅 접기 ▾":"채팅 열기 ▴";
  b.setAttribute("aria-expanded",String(MOBILE_CHAT_OPEN));
  if(MOBILE_CHAT_OPEN) renderChat(true);
  chatUnreadRefresh();
}
function toggleNav(id){
 const g=NAVDEF.find(x=>x.id===id);if(!g?.sub)return;
 const opening=!navOpen(g);
 for(const group of NAVDEF)if(group.sub)NAVOPEN[group.id]=opening&&group.id===id;
 renderNav();
}
function go(v){
  VIEW=v;
  const g=NAVDEF.find(x=>x.sub&&x.sub.some(s=>s.id===v));
  for(const group of NAVDEF)if(group.sub)NAVOPEN[group.id]=group===g;
  renderNav(); renderMain(); window.scrollTo({top:0,behavior:"smooth"});
}

/* ── 채팅 ── */
const CHATTABS=["전체","이웃","계통","모임","페어"];
function chatModeOf(mode){ return mode==="오너"||mode==="사담"?"오너":"RP"; }
function chatMessages(){
  return S.msgs.filter(chatVisible)
    .filter(m=>!["RP","오너"].includes(S.chatFilter)||chatModeOf(m.mode)===S.chatFilter)
    .sort(chatSort).slice(-120);
}
function chatMessageHTML(m){
  const mode=chatModeOf(m.mode);
  return `<div class="cmsg"><span class="ctime">${esc(m.time||"")}</span>
    <div class="cbody"><span class="cmode ${mode==="오너"?"owner":"rp"}">${mode}</span>${m.title?`<span class="ctitle">${esc(m.title)}</span> `:""}<b class="cname" style="color:${m.tab==="모임"&&m._clubVerified===true&&typeof clubSoulColor==="function"?clubSoulColor(m):m.c||"var(--violetL)"}">${esc(m.who)}</b> ${m.failed?`<span class="ctitle" style="color:var(--red)">전송 실패 · 다시 보내 주세요</span> `:m.pending?`<span class="ctitle">전송 중</span> `:""}${m.body}</div></div>`;
}
let CHATRESIZE=null;
function chatLayout(){
  const top=document.getElementById("topbar");
  if(!top) return;
  const fit=()=>{
    const height=top.getBoundingClientRect().height;
    document.documentElement.style.setProperty("--chat-top",Math.ceil(height+16)+"px");
    document.documentElement.style.setProperty("--mobile-top-height",height+"px");
  };
  fit();
  if(!CHATRESIZE&&typeof ResizeObserver!=="undefined"){
    CHATRESIZE=new ResizeObserver(fit); CHATRESIZE.observe(top);
  }
  const log=document.getElementById("chatlog");
  if(log&&!log._layoutObserver&&typeof ResizeObserver!=="undefined"){
    // Keep the latest message visible when buffs change the available height.
    // Reading older messages and the compose input remain untouched.
    let follow=log.scrollHeight-log.clientHeight-log.scrollTop<48;
    log.addEventListener("scroll",()=>{follow=log.scrollHeight-log.clientHeight-log.scrollTop<48;},{passive:true});
    log._layoutObserver=new ResizeObserver(()=>{if(follow)log.scrollTop=log.scrollHeight;});
    log._layoutObserver.observe(log);
  }
}
/* 대화 칸 접기 — 넓은 화면에서 대화가 비어 있을 때 본문에 자리를 돌려줍니다.
   선택은 이 브라우저에 남습니다. 좁은 화면에서는 쓰이지 않습니다. */
const CHAT_READ_CACHE={key:null,seen:new Set()};
function chatReadState(){
 const key=updateNoticeStorageKey()+':chat';
 if(CHAT_READ_CACHE.key!==key){let values=[];try{values=JSON.parse(localStorage.getItem(key)||'[]');}catch(_){}
  CHAT_READ_CACHE.key=key;CHAT_READ_CACHE.seen=new Set(Array.isArray(values)?values.map(String):[]);
 }
 return CHAT_READ_CACHE;
}
function chatUnreadCandidates(tab){
 if(!S?.msgs)return [];
 const previous=S.chatTab;
 try{return S.msgs.filter(m=>{
  if(m.sid===undefined||m.sid===null||m.mine||m.pending||m.failed||!CHATTABS.includes(m.tab)||(tab&&m.tab!==tab))return false;
  S.chatTab=m.tab;return chatVisible(m);
 });}finally{S.chatTab=previous;}
}
function chatUnreadCount(tab){const state=chatReadState();return chatUnreadCandidates(tab).filter(m=>!state.seen.has(String(m.sid))).length;}
function chatCanMarkRead(){
 if(document.visibilityState==='hidden')return false;
 if(window.matchMedia('(max-width:780px)').matches&&!MOBILE_CHAT_OPEN)return false;
 if(!window.matchMedia('(max-width:780px)').matches&&chatFolded())return false;
 const log=document.getElementById('chatlog');if(!log||log.getClientRects().length===0)return false;
 const bounds=log.getBoundingClientRect();if(bounds.bottom<=0||bounds.top>=window.innerHeight)return false;
 return log.scrollHeight-log.clientHeight-log.scrollTop<48;
}
function chatUnreadRefresh(){
 const state=chatReadState();
 if(chatCanMarkRead()){
  let changed=false;for(const m of chatUnreadCandidates(S.chatTab).filter(m=>!['RP','오너'].includes(S.chatFilter)||chatModeOf(m.mode)===S.chatFilter)){if(m.sid!==undefined&&m.sid!==null&&!state.seen.has(String(m.sid))){state.seen.add(String(m.sid));changed=true;}}
  if(changed){const values=[...state.seen].slice(-1500);state.seen=new Set(values);try{localStorage.setItem(state.key,JSON.stringify(values));}catch(_){}}
 }
 const count=chatUnreadCount();
 for(const selector of ['#mobile-chat-toggle','.chat-fold']){
  const button=document.querySelector(selector);if(!button)continue;
  button.querySelector('.chat-unread-count')?.remove();if(count)button.insertAdjacentHTML('beforeend',unreadCountHTML(count,'chat-unread-count'));
 }
 document.querySelectorAll('[data-chat-tab]').forEach(button=>{button.querySelector('.chat-unread-count')?.remove();const n=chatUnreadCount(button.dataset.chatTab);if(n)button.insertAdjacentHTML('beforeend',unreadCountHTML(n,'chat-unread-count'));});
}
const CHATFOLDKEY="mmjy.chatFold";
function chatFolded(){ try{ return localStorage.getItem(CHATFOLDKEY)==="1"; }catch(e){ return false; } }
function applyChatFold(){
  const off=chatFolded();
  document.body.classList.toggle("chat-off", off);
  const b=document.querySelector(".chat-fold");
  if(b){ b.title=off?"대화 칸 펴기":"대화 칸 접기"; b.setAttribute("aria-expanded", String(!off)); }
}
function toggleChat(){
  try{ localStorage.setItem(CHATFOLDKEY, chatFolded()?"0":"1"); }catch(e){}
  applyChatFold();
  renderChat();
}
function renderChat(bottom=false){
  const host=$("#chatcol"); if(!host) return;
  S.chatMode=chatModeOf(S.chatMode);
  if(!["모두","RP","오너"].includes(S.chatFilter)) S.chatFilter="모두";
  /* 입력칸은 다시 만들지 않습니다. 새 글을 받아도 초안·커서·한글 조합이 유지됩니다. */
  if(!host.querySelector(".chat-panel")) host.innerHTML=`
  <section class="card chat-panel" aria-label="채팅">
    <button type="button" class="chat-fold" onclick="toggleChat()" aria-expanded="true"
      aria-controls="chatlog" title="대화 칸 접기"><span>대화</span>${ic("chevR",12)}</button>
    <div class="chat-tabs" id="chattabs" aria-label="채팅 채널"></div>
    <div class="chat-toolbar">
      <span class="tiny muted">보기</span><span class="seg" id="chatfilters" aria-label="대화 필터"></span>
      <span class="tiny muted chat-scope" id="chatscope"></span>
    </div>
    <div class="chat-context" id="chatcontext"></div>
    <div class="chat-log" id="chatlog" role="log" aria-label="채팅 기록" aria-live="polite" tabindex="0"></div>
    <div class="chat-compose">
      <div class="chat-compose-mode"><span class="tiny muted">보내기</span><span class="seg" id="chatmodes" aria-label="전송 모드"></span></div>
      <div class="chat-in">
        <input id="chatinput" aria-label="채팅 메시지" autocomplete="off" onkeydown="if(event.key==='Enter'&&!event.isComposing&&event.keyCode!==229){event.preventDefault();sendChat()}">
        <button class="btn pri sm" onclick="sendChat()">보내기</button>
      </div>
    </div>
  </section>`;
  if(!host._chatFoldReady){ host._chatFoldReady=true; applyChatFold(); }
  const update=(id,html)=>{ const el=document.getElementById(id); if(el._chatHTML!==html){el.innerHTML=html;el._chatHTML=html;} };
  update("chattabs",CHATTABS.map(t=>`<button class="ctab ${S.chatTab===t?"on":""}" data-chat-tab="${esc(t)}" aria-pressed="${S.chatTab===t}" onclick="setChatTab('${t}')">${t}</button>`).join(""));
  update("chatfilters",["모두","RP","오너"].map(t=>`<button class="${S.chatFilter===t?"on":""}" aria-pressed="${S.chatFilter===t}" onclick="setChatFilter('${t}')">${t}</button>`).join(""));
  update("chatmodes",["RP","오너"].map(t=>`<button class="${S.chatMode===t?"on":""}" aria-pressed="${S.chatMode===t}" onclick="setChatMode('${t}')">${t}</button>`).join(""));
  $("#chatscope").textContent=S.chatTab==="계통"?S.line+" 학생끼리":S.chatTab==="이웃"?homeOf(S.hall).n:S.chatTab==="페어"?"페어끼리":S.chatTab==="1:1"?(S.dmWith?.name||"상대 선택"):"전원 · 교직원 NPC는 RP에만 등장";
  update("chatcontext",typeof chatContextHTML==="function"?chatContextHTML():"");
  $("#chatinput").placeholder=S.chatMode==="RP"?"대사와 *행동* 또는 (행동)을 입력하세요":"오너 대화를 입력하세요";
  chatLayout();
  const list=chatMessages(), log=$("#chatlog");
  const view=JSON.stringify([S.chatTab,typeof chatScope==="function"?chatScope(S.chatTab):"",S.chatFilter]);
  const follow=bottom||host._chatView!==view||log.scrollHeight-log.clientHeight-log.scrollTop<48;
  const html=list.map(chatMessageHTML).join("")||`<div class="tiny muted" style="padding:14px 2px">${S.chatFilter==="모두"?"아직 오간 말이 없습니다.":S.chatFilter+" 대화가 아직 없습니다."}</div>`;
  if(log._chatHTML!==html){
    const oldTop=log.scrollTop, bounds=log.getBoundingClientRect();
    const anchor=follow?-1:[...log.children].findIndex(el=>el.getBoundingClientRect().bottom>bounds.top);
    const msg=host._chatMessages?.[anchor], offset=anchor<0?0:log.children[anchor].getBoundingClientRect().top-bounds.top;
    log.innerHTML=html; log._chatHTML=html;
    const next=list.indexOf(msg);
    if(!follow) log.scrollTop=next<0?oldTop:log.scrollTop+log.children[next].getBoundingClientRect().top-log.getBoundingClientRect().top-offset;
  }
  if(follow) log.scrollTop=log.scrollHeight;
  host._chatView=view; host._chatMessages=list;
  if(!log._unreadReady){log._unreadReady=true;log.addEventListener('scroll',chatUnreadRefresh,{passive:true});}
  chatUnreadRefresh();
}
function setChatTab(t){ if(!CHATTABS.includes(t)) return; S.chatTab=t; renderChat(); save(); }
function setChatFilter(m){
  if(!["모두","RP","오너"].includes(m)) return;
  S.chatFilter=m;
  if(m!=="모두") S.chatMode=m;
  renderChat(); save();
}
function setChatMode(m){
  S.chatMode=chatModeOf(m);
  if(["RP","오너"].includes(S.chatFilter)) S.chatFilter=S.chatMode;
  renderChat(); save();
}
function fmtChat(value){
 const text=String(value??'');let out='',i=0,plain='';
 const flush=()=>{out+=esc(plain);plain='';};
 while(i<text.length){
  if(text[i]==='*'&&text[i+1]!=='*'&&text[i-1]!=='*'){
   const end=text.indexOf('*',i+1);
   if(end>i+1&&text[end+1]!=='*'){flush();out+='<span class="rp-action">'+esc(text.slice(i+1,end))+'</span>';i=end+1;continue;}
  }
  if(text[i]==='('){let depth=1,j=i+1;for(;j<text.length&&depth;j++){if(text[j]==='(')depth++;else if(text[j]===')')depth--;}
   if(!depth){flush();out+='<span class="rp-action">'+esc(text.slice(i,j))+'</span>';i=j;continue;}
  }
  plain+=text[i++];
 }
 flush();return out.replace(/\n/g,'<br>');
}
function addMsg(tab,who,body,c,title,extra){
  const m=Object.assign({tab,who,body,c,title,mode:chatModeOf(S.chatMode),ts:Date.now(),
    time:cal().str.replace(/^(오전|오후) /,"")}, extra||{});
  S.msgs.push(m);
  if(S.msgs.length>400) S.msgs.shift();
  return m;
}
/* 이 글을 지금 탭에서 보여 줄지 — part6 가 채널 범위까지 따져 덮어씁니다 */
function chatVisible(m){ return m.tab===S.chatTab; }
function chatSort(a,b){ return (a.ts||0)-(b.ts||0); }
function sendChat(){
  const i=$("#chatinput"); if(!i||!i.value.trim()) return;
  const m=addMsg(S.chatTab, S.name, fmtChat(i.value.trim()), S.color, S.course+"과정",
    {scope:typeof chatScope==="function"?chatScope(S.chatTab):"",mine:true});
  i.value=""; renderChat(true); save();
  // NPC 응답은 서버의 메시지 트리거가 생성합니다. 클라이언트에서 재추첨하지 않습니다.
  return m;
}
const CHATPOOL={
 RP:["*창밖을 본다.* 오늘도 해가 없네.","의뢰 다녀온 사람? 3구역 쪽 어땠어.","*부적을 접다 말고 고개를 든다.*","다친 데 있으면 보건실 가. 삼장 선생 계셔.","공명 조율이 영 안 맞아. 손실이 너무 커.","*동전을 세어 본다.* 이번 주 륜이 벌써 바닥이야.","야시장 갈 사람. 혼자는 좀 그래서.","어제 꿈에 모르는 골목이 나왔어. 또.","석탑 종 울린 거 들었어? 몇 구역이래?","*가볍게 목을 돌린다.* 몸이 무겁다.","페어 어디 갔는지 본 사람 있어?","수업 하나 더 들을까 하다가 그냥 왔어."],
 사담:["오늘 수업 효율 왜 이럼","탕약 가격 또 올랐더라","의뢰 Ⅲ등급부터 체감 확 다름","연구는 진짜 시간 싸움임","파장 재생 먼저 올리는 게 맞는 듯","정신력은 5에서 막혀서 애매함","시험 이론 점수 과목 평균으로 채점됨 참고","나들이 통행패 모아뒀다가 한 번에 쓰는 중","공명 적성 올리면 확실히 체감됨","강시 노래 진짜 못함 ㅋㅋㅋ"],
};
let RECENTLINES=[];
function freshLine(pool){
  for(let i=0;i<12;i++){ const l=pick(pool); if(!RECENTLINES.includes(l)){ RECENTLINES.push(l); if(RECENTLINES.length>14)RECENTLINES.shift(); return l; } }
  return pick(pool);
}
function npcChat(){
  // 공유 NPC 채팅은 서버에서만 생성됩니다. 과거의 로컬 자동 채팅을 비활성화합니다.
  return null;
}

/* ═══════════════════════════════════════════════════
   메인 화면 디스패치
   ═══════════════════════════════════════════════════ */
const VIEWS={};
const MAIN_DISCLOSURES=new Map();
function renderMain(soft){
  const ae=document.activeElement;
  if(soft && ae && /^(INPUT|TEXTAREA|SELECT)$/.test(ae.tagName)) return;
  const sc=window.scrollY;
  // '고르기', 시간 변경 등의 수동 갱신 때도 열린 의뢰 목록 유지.
  const questListOpen=VIEW==="quest" && !!document.getElementById("quest-stage-picker")?.open;
  // Keep explicitly keyed disclosures at the state the reader last chose.
  document.querySelectorAll('#main details[data-disclosure-key]').forEach(el=>MAIN_DISCLOSURES.set(el.dataset.disclosureKey,el.open));
  const f=VIEWS[VIEW]||VIEWS.plaza;
  $("#main").innerHTML=f();
  document.querySelectorAll('#main details[data-disclosure-key]').forEach(el=>{
    if(MAIN_DISCLOSURES.has(el.dataset.disclosureKey))el.open=MAIN_DISCLOSURES.get(el.dataset.disclosureKey);
  });
  if(questListOpen){ const picker=document.getElementById("quest-stage-picker"); if(picker) picker.open=true; }
  if(soft) window.scrollTo(0,sc);
}
function head(kicker,title,right){
  return `<div class="page-head"><div>
    <div class="page-kicker">${kicker}</div><h1 class="page">${title}</h1>
  </div>${right?`<div class="rt">${right}</div>`:""}</div>`;
}

/* 공동 저장에서 수업과 수행을 분 단위로 서버 확정하더라도,
   광장의 남은 시간은 별도 서버 요청 없이 부드럽게 표시합니다. */
function pairDisplayRemaining(left,kind){
 const pair=window.PAIR_PLAY;
 if(!pair?.ready)return left;
 const anchor=kind==='pass'?Number(pair.lastServerReadAt):Number(pair.clockBasis);
 if(!Number.isFinite(anchor)||anchor<=0)return left;
 return Math.max(0,Number(left)-Math.max(0,(Date.now()-anchor)/60000));
}
function pairLiveTimer(kind,left){
 const remaining=pairDisplayRemaining(left,kind);
 if(!window.PAIR_PLAY?.ready)return hhmm(remaining);
 return `<span class="pair-live-clock" data-clock="${kind}">${hhmm(remaining)}</span>`;
}
/* 광장 활동 요약. 의뢰는 별도의 실시간 타이머를 사용하므로 현재 잔여치를 읽습니다. */
function plazaActivityHTML(){
  if(!S || !S.made) return "";
  const rows=[];
  const row=(kind,name,detail,left,view)=>{
    const time=Number.isFinite(Number(left))?`<b class="activity-countdown" style="color:var(--gold)">${hhmm(Math.max(0,Number(left)))}</b> 남음`:"진행 중";
    rows.push(`<div class="activity-row">
      <div><span class="tag j">${kind}</span> <b>${esc(name)}</b><div class="tiny muted">${esc(detail||"")}</div></div>
      <div class="activity-actions"><span class="tiny">${time}</span><button class="btn sm" onclick="go('${view}')">보기</button></div>
    </div>`);
  };
  if(S.lesson){
    const sb=SUBJECTS.find(x=>x.id===S.lesson.plan?.[S.lesson.idx]);
    row("수업",sb?.n||"진행 중인 수업",`${(S.lesson.idx||0)+1} / ${S.lesson.plan?.length||1}교시`,pairDisplayRemaining(S.lesson.left),"class");
  }
  if(S.run&&!S.run.done){
    const r=S.run;
    row("의뢰",r.q?.t||r.q?.title||"현장 의뢰",`현재 구간 ${r.stage||r.q?.stage||"?"} · 처치 ${r.kills||0}체`,pairDisplayRemaining(r.left),"quest");
  }
  if(S.study){
    const r=RESEARCH.find(x=>x.id===S.study.id);
    row("수행",r?.n||"수행 중", "연구 진행 중",pairDisplayRemaining(S.study.left),"research");
  }
  if(S.book){
    const b=BOOKS.find(x=>x.id===S.book.id);
    row("고서",b?.n||"고서 열람","열람 효과 유지 중",pairDisplayRemaining(S.book.left),"research");
  }
  if(coolLeft("rest")>0) row("휴식","보건실 재방문","휴식 재사용 대기시간",coolLeft("rest"),"plaza");
  if(S.pass<3&&S.passNext>0) row("충전","통행패 발급",`현재 ${S.pass}/3장`,pairDisplayRemaining(S.passNext,"pass"),"map");
  if(typeof LIVE_AUCTION!=="undefined"&&LIVE_AUCTION.data){
    const auction=LIVE_AUCTION.data;
    const live=(auction.live||[]).find(l=>Date.parse(l.ends_at)>LIVE_AUCTION.offset+Date.now());
    const when=live?live.ends_at:auction.next_at;
    const mins=Math.max(0,(Date.parse(when)-(Date.now()+LIVE_AUCTION.offset))/60000);
    if(Number.isFinite(mins))row("상인",live?"경매 진행 중":"다음 경매 개장",live?"러너 공동 입찰 진행 중":"매시 정각 개장",mins,"merchant");
  }
  if(!rows.length)return `<div class="tiny muted" style="padding:7px 0">현재 진행 중인 수업이나 의뢰가 없습니다. <a style="color:var(--gold);cursor:pointer" onclick="go('quest')">의뢰 보러 가기 →</a></div>`;
  return rows.join("");
}
function plazaActivityRefresh(){
  if(!S?.made)return;
  if(window.PAIR_PLAY?.ready){
    // Updating a few text nodes avoids a full screen re-render just to advance
    // a countdown, and prevents 2-minute passive saves from freezing timers.
    const timers={lesson:S.lesson?.left,study:S.study?.left,book:S.book?.left,pass:S.passNext};
    document.querySelectorAll('.pair-live-clock').forEach(el=>{
      const kind=el.getAttribute('data-clock');
      if(Number.isFinite(Number(timers[kind]))){
        const text=hhmm(pairDisplayRemaining(timers[kind],kind));
        if(el.textContent!==text)el.textContent=text;
      }
    });
  }
  if(VIEW!=="plaza")return;
  const box=document.getElementById("plaza-active-list");
  if(box)box.innerHTML=plazaActivityHTML();
}
setInterval(plazaActivityRefresh,1000);
/* ───────────── 사무전 광장 ───────────── */
